import logoSvg from '../assets/gaji-labo-logo.svg?raw'

import './logo.css'

/** Gaji-Labo のロゴ（currentColor で塗られる SVG）。Header の上では白で表示する。 */
export const GajiLaboLogo = ({ tone = 'white' }: { tone?: 'white' | 'black' }) => (
  <span
    className="ct-logo"
    data-tone={tone}
    role="img"
    aria-label="Gaji-Labo（新しいタブで開きます）"

    dangerouslySetInnerHTML={{ __html: logoSvg.replace(/<metadata>[\s\S]*?<\/metadata>/, '') }}
  />
)

import { type ReactNode, useEffect } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import {
  AppNavi,
  AppNaviCustomTag,
  Button,
  Cluster,
  FaGearIcon,
  FaRightFromBracketIcon,
  FaRightToBracketIcon,
  Header,
  HeaderDropdownMenuButton,
  NotificationBar,
  Text,
  useEnvironment,
} from 'smarthr-ui'

import { useAppState } from '../state'

import { GajiLaboLogo } from './GajiLaboLogo'
import { Avatar } from './Person'
import { NaviLink } from './RouterTextLink'

const LOGO_LINK_SELECTOR = '.smarthr-ui-Header-logoLink'

export const Layout = ({ title, children }: { title: string; children: ReactNode }) => {
  const { me, login, logout, notice, setNotice } = useAppState()
  const { pathname, search } = useLocation()
  const navigate = useNavigate()
  const { mobile } = useEnvironment()

  useEffect(() => {
    // ページタイトル：「画面名｜サービス名」[D:ui-text/app-writing]
    document.title = `${title}｜CTスケジュール`
  }, [title])

  useEffect(() => {
    // Header のロゴリンクは target を指定できないため、別タブで開くよう属性を補う（妥協点として記録）。
    document.querySelectorAll<HTMLAnchorElement>(LOGO_LINK_SELECTOR).forEach((a) => {
      a.target = '_blank'
      a.rel = 'noopener noreferrer'
    })
  })

  return (
    <div className="shr-min-h-screen shr-bg-background">
      <Header logo={<GajiLaboLogo />} logoHref="https://www.gaji.jp/">
        {me ? (
          <HeaderDropdownMenuButton
            trigger={
              <Cluster inline align="center" as="span">
                <Avatar member={me} />
                <Text color="TEXT_WHITE">{me.name}</Text>
              </Cluster>
            }
          >
            <Button prefix={<FaGearIcon />} onClick={() => navigate(`/settings${search}`)}>
              自分の設定を変更
            </Button>
            <Button prefix={<FaRightFromBracketIcon />} onClick={logout}>
              ログアウト
            </Button>
          </HeaderDropdownMenuButton>
        ) : (
          <Button size="S" prefix={<FaRightToBracketIcon />} onClick={login}>
            Slack でログイン
          </Button>
        )}
      </Header>
      {/* モバイルではラベルを省き、3 つのナビゲーションを横幅に収める */}
      <AppNavi label={mobile ? undefined : 'CTスケジュール'}>
        <AppNaviCustomTag tag={NaviLink} href="/" current={pathname === '/'}>
          組み合わせ
        </AppNaviCustomTag>
        <AppNaviCustomTag tag={NaviLink} href="/members" current={pathname === '/members'}>
          メンバー
        </AppNaviCustomTag>
        {me && (
          <AppNaviCustomTag tag={NaviLink} href="/settings" current={pathname === '/settings'}>
            自分の設定
          </AppNaviCustomTag>
        )}
      </AppNavi>
      {notice && (
        <NotificationBar
          type={notice.type}
          bold
          animate
          onClose={() => setNotice(null)}
          className="shr-sticky shr-top-0 shr-z-1"
          subActionArea={
            notice.action === 'retryLogin' ? (
              <Button size="S" prefix={<FaRightToBracketIcon />} onClick={login}>
                もう一度ログインする
              </Button>
            ) : undefined
          }
        >
          {notice.text}
        </NotificationBar>
      )}
      {children}
    </div>
  )
}

import { useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import {
  Button,
  Center,
  Cluster,
  Container,
  DefinitionList,
  DefinitionListItem,
  FaArrowRotateRightIcon,
  FaRightToBracketIcon,
  Heading,
  InformationPanel,
  Loader,
  NotificationBar,
  PageHeading,
  Panel,
  Reel,
  ResponseMessage,
  Section,
  Stack,
  StatusLabel,
  TabBar,
  TabItem,
  Text,
  WarningIcon,
  useEnvironment,
} from 'smarthr-ui'

import { Layout } from '../components/Layout'
import { Person } from '../components/Person'
import { RouterTextLink } from '../components/RouterTextLink'
import { type Member, type Week, fullDateLabel, huddleChannel } from '../data/model'
import { useAppState } from '../state'

const START_TIME = '14:00'

/** ハドル開始の操作。デモのため通知だけを出す。フィードバックはボタンの近くに出す [H:feedback] */
const HuddleButton = ({
  channel,
  variant,
  partnerLabel,
}: {
  channel: string
  variant: 'primary' | 'secondary'
  /** 読み上げ用：誰とのハドルか */
  partnerLabel: string
}) => {
  const [started, setStarted] = useState(false)
  const { mobile } = useEnvironment()
  return (
    <Stack gap={0.5} align={mobile ? 'stretch' : 'flex-start'}>
      <Button variant={variant} wide={mobile} onClick={() => setStarted(true)} aria-label={`${partnerLabel}とハドルを始める`}>
        ハドルを始める
      </Button>
      <Text size="S" color="TEXT_GREY">
        場所：#{channel}
      </Text>
      {started && (
        <ResponseMessage role="status">
          デモのため Slack には接続しません。本番では #{channel} でハドルが始まります。
        </ResponseMessage>
      )}
    </Stack>
  )
}

type MyWeek =
  | { kind: 'pair'; partner: Member; channel?: string }
  | { kind: 'rest' }
  | { kind: 'holiday'; name: string }
  | { kind: 'none' }
  | { kind: 'inactive' }

const myWeek = (week: Week, me: Member, find: (id: number) => Member | undefined): MyWeek => {
  if (week.holiday) return { kind: 'holiday', name: week.holiday }
  if (!me.active) return { kind: 'inactive' }
  const pair = week.pairs.find((p) => p.includes(me.id))
  if (pair) {
    const partner = find(pair[0] === me.id ? pair[1] : pair[0])
    if (partner) return { kind: 'pair', partner, channel: huddleChannel(me, partner) }
  }
  if (week.rest === me.id) return { kind: 'rest' }
  return { kind: 'none' }
}

/** 主役：今週のあなたの相手とハドル開始 [H:visual-guidance 上部に重要な情報][H:Button Primary は 1 つ] */
const MyThisWeek = () => {
  const { me, weeks, members } = useAppState()
  if (!me) return null
  const find = (id: number) => members.find((m) => m.id === id)
  const [thisWeek, ...upcoming] = weeks
  const current = myWeek(thisWeek, me, find)

  return (
    <Section>
      <Stack>
        <Heading>今週のあなたの相手</Heading>
        <Panel padding={1.5}>
          <Stack gap={1.5}>
            <Stack>
              <Text size="S" color="TEXT_GREY">
                {fullDateLabel(thisWeek)} {START_TIME} から
              </Text>
              {current.kind === 'pair' && (
                <>
                  <Person member={current.partner} size="L" />
                  {current.channel ? (
                    <HuddleButton channel={current.channel} variant="primary" partnerLabel={current.partner.name} />
                  ) : (
                    <Text as="p" icon={<WarningIcon />}>
                      {current.partner.name}さんの uチャンネルが未設定のため、ここからはハドルを始められません。Slack
                      で直接連絡してください。
                    </Text>
                  )}
                </>
              )}
              {current.kind === 'rest' && (
                <Stack gap={0.5}>
                  <Text size="XL" weight="bold">
                    今週、あなたはお休みです
                  </Text>
                  <p>参加者が奇数のため、毎週 1 人がお休みになります。お休みの人は週ごとに入れ替わります。</p>
                </Stack>
              )}
              {current.kind === 'holiday' && (
                <Text size="XL" weight="bold">
                  今週は {current.name} のため CT はありません
                </Text>
              )}
              {current.kind === 'inactive' && (
                <Stack gap={0.5}>
                  <Text size="XL" weight="bold">
                    あなたは今、CT に参加していません
                  </Text>
                  <p>
                    参加すると、次の組み合わせから入ります。<RouterTextLink href="/settings">自分の設定で参加する</RouterTextLink>
                  </p>
                </Stack>
              )}
              {current.kind === 'none' && (
                <Stack gap={0.5}>
                  <Text size="XL" weight="bold">
                    今週の組み合わせはありません
                  </Text>
                  <p>参加者が 2 人未満のため、組み合わせを作れません。2 人以上が参加すると作られます。</p>
                </Stack>
              )}
            </Stack>
            {me.active && upcoming.length > 0 && (
              <Section>
                <Stack gap={0.5}>
                  <Heading type="blockTitle">あなたの今後の予定</Heading>
                <DefinitionList>
                  {upcoming.map((w) => {
                    const v = myWeek(w, me, find)
                    return (
                      <DefinitionListItem key={w.key} term={`${w.short}（月）`} maxColumns={4}>
                        {v.kind === 'pair' && <Person member={v.partner} />}
                        {v.kind === 'rest' && 'お休み'}
                        {v.kind === 'holiday' && `CT なし（${v.name}）`}
                        {v.kind === 'none' && '組み合わせなし'}
                      </DefinitionListItem>
                    )
                  })}
                </DefinitionList>
                <Text size="S" color="TEXT_GREY" as="p">
                  先の週は予定です。参加者が増減すると組み直されます。
                </Text>
                </Stack>
              </Section>
            )}
          </Stack>
        </Panel>
      </Stack>
    </Section>
  )
}

/** 未ログインの人に、ログインすると何ができるかを伝える */
const LoginGuide = () => {
  const { login } = useAppState()
  return (
    <InformationPanel heading="ログインすると、あなたの相手がすぐにわかります">
      <Stack>
        <p>
          Slack でログインすると、今週のあなたの相手がこの画面の一番上に表示され、そのままハドルを始められます。参加状況などの自分の設定も変えられます。
        </p>
        <div>
          <Button variant="primary" prefix={<FaRightToBracketIcon />} onClick={login}>
            Slack でログイン
          </Button>
        </div>
      </Stack>
    </InformationPanel>
  )
}

const tabLabel = (w: Week, i: number) => (i === 0 ? '今週' : i === 1 ? '来週' : w.short)

/** 1 週分の組み合わせ */
const WeekPanel = ({ week, isThisWeek }: { week: Week; isThisWeek: boolean }) => {
  const { me, members } = useAppState()
  const find = (id: number) => members.find((m) => m.id === id)
  const restMember = week.rest ? find(week.rest) : undefined
  const mark = (m: Member) => (me && m.id === me.id ? 'あなた' : undefined)

  return (
    <Panel padding={1.5}>
      <Section>
      <Stack gap={1.5}>
        <Cluster align="center">
          <Heading type="blockTitle">
            {fullDateLabel(week)} {week.holiday ? '' : `${START_TIME} から`}
          </Heading>
          {week.holiday ? <StatusLabel>CT なし</StatusLabel> : !isThisWeek && <StatusLabel>予定</StatusLabel>}
        </Cluster>
        {week.holiday ? (
          <p>
            {week.holiday}のため、この週の CT はありません。組み合わせは作らず、翌週に繰り越します。
          </p>
        ) : week.pairs.length === 0 ? (
          <Center padding={1.5}>
            <Stack gap={0.5} align="center">
              <p>組み合わせはありません。</p>
              <Text as="p" size="S" color="TEXT_GREY">
                参加者が 2 人未満のためです。2 人以上が参加すると組み合わせが作られます。
              </Text>
              <RouterTextLink href="/members">参加状況をメンバー画面で確認する</RouterTextLink>
            </Stack>
          </Center>
        ) : (
          <Stack>
            <Stack as="ul" className="shr-list-none shr-ps-0">
              {week.pairs.map(([aId, bId]) => {
                const a = find(aId)
                const b = find(bId)
                if (!a || !b) return null
                const channel = huddleChannel(a, b)
                return (
                  <li key={`${aId}-${bId}`}>
                    <Cluster justify="space-between" align="center" gap={1}>
                      <Cluster align="center" gap={{ row: 0.5, column: 1 }}>
                        <Person member={a} note={mark(a)} />
                        <Text color="TEXT_GREY">と</Text>
                        <Person member={b} note={mark(b)} />
                      </Cluster>
                      {isThisWeek &&
                        (channel ? (
                          <HuddleButton channel={channel} variant="secondary" partnerLabel={`${a.name}さんと${b.name}さん`} />
                        ) : (
                          <Text size="S" color="TEXT_GREY">
                            uチャンネル未設定のためハドル不可
                          </Text>
                        ))}
                    </Cluster>
                  </li>
                )
              })}
            </Stack>
            {restMember && (
              <Cluster align="center">
                <Text weight="bold">お休み</Text>
                <Person member={restMember} note={mark(restMember)} />
              </Cluster>
            )}
            {!isThisWeek && (
              <Text as="p" size="S" color="TEXT_GREY">
                この週の組み合わせは予定です。参加者が増減すると組み直されます。
              </Text>
            )}
          </Stack>
        )}
      </Stack>
      </Section>
    </Panel>
  )
}

/** 週ごとの組み合わせ。TabBar でセクションの内容を切り替える [H:visual-grouping][H:page-layout 長いページを避ける] */
const WeeksSection = () => {
  const { weeks, members } = useAppState()
  const [params, setParams] = useSearchParams()
  const selectedKey = params.get('week') ?? weeks[0].key
  const selectedIndex = Math.max(
    0,
    weeks.findIndex((w) => w.key === selectedKey),
  )
  const activeCount = members.filter((m) => m.active).length

  return (
    <Section>
      <Stack>
        <Cluster justify="space-between" align="center" gap={1}>
          <Heading>週ごとの組み合わせ</Heading>
          <Cluster align="center" gap={1}>
            <span>参加者 {activeCount} 人</span>
            <RouterTextLink href="/members">メンバーを見る</RouterTextLink>
          </Cluster>
        </Cluster>
        <Reel>
          <TabBar bordered>
            {weeks.map((w, i) => (
              <TabItem
                key={w.key}
                id={`week-tab-${w.key}`}
                selected={i === selectedIndex}
                onClick={() => {
                  const next = new URLSearchParams(params)
                  next.set('week', w.key)
                  setParams(next, { replace: true })
                }}
              >
                {tabLabel(w, i)}
              </TabItem>
            ))}
          </TabBar>
        </Reel>
        <div role="tabpanel" aria-label={`${tabLabel(weeks[selectedIndex], selectedIndex)}の組み合わせ`}>
          <WeekPanel week={weeks[selectedIndex]} isThisWeek={selectedIndex === 0} />
        </div>
      </Stack>
    </Section>
  )
}

export const Home = () => {
  const { me, load, reload } = useAppState()
  return (
    <Layout title="組み合わせ">
      <Container>
        <Stack gap={2}>
          <Stack gap={0.5}>
            <PageHeading>CT の組み合わせ</PageHeading>
            <p>
              毎週月曜 {START_TIME} から、2 人 1 組で話します（CT＝コミュニケーションタイム）。組み合わせは毎週月曜 11:00 に Slack
              にも投稿されます。
            </p>
          </Stack>
          {load === 'loading' && (
            <Center padding={3}>
              <Loader text="組み合わせを読み込んでいます" />
            </Center>
          )}
          {load === 'error' && (
            <NotificationBar
              type="error"
              bold
              paneled
              subActionArea={
                <Button size="S" prefix={<FaArrowRotateRightIcon />} onClick={reload}>
                  再読み込み
                </Button>
              }
            >
              組み合わせを読み込めませんでした。通信状況を確認して、再読み込みしてください。
            </NotificationBar>
          )}
          {load === 'ready' && (
            <>
              {me ? <MyThisWeek /> : <LoginGuide />}
              <WeeksSection />
            </>
          )}
        </Stack>
      </Container>
    </Layout>
  )
}

import { useState } from 'react'
import {
  Button,
  Center,
  Cluster,
  Container,
  ControlledActionDialog,
  DefinitionList,
  DefinitionListItem,
  EmptyTableBody,
  FaRightToBracketIcon,
  FaTrashCanIcon,
  Heading,
  PageHeading,
  Panel,
  Section,
  Stack,
  StatusLabel,
  Table,
  Td,
  Text,
  Th,
  WarningIcon,
  useEnvironment,
} from 'smarthr-ui'

import { Layout } from '../components/Layout'
import { Person } from '../components/Person'
import { RouterTextLink } from '../components/RouterTextLink'
import { type Member, empCode, isIncomplete } from '../data/model'
import { useAppState } from '../state'

/** 参加／不参加。色だけでなく文字で区別する [H:StatusLabel] */
const ActiveLabel = ({ member }: { member: Member }) =>
  <StatusLabel type={member.active ? 'blue' : 'grey'}>{member.active ? '参加' : '不参加'}</StatusLabel>

const IncompleteNote = ({ member }: { member: Member }) =>
  isIncomplete(member) ? (
    <Text size="S" icon={<WarningIcon />}>
      初回設定が未完了
    </Text>
  ) : null

const DeleteButton = ({ member, onClick, iconOnly }: { member: Member; onClick: () => void; iconOnly?: boolean }) =>
  iconOnly ? (
    <Button onClick={onClick} aria-label={`${member.name}さんを削除`}>
      <FaTrashCanIcon alt={`${member.name}さんを削除`} />
    </Button>
  ) : (
    <Button size="S" prefix={<FaTrashCanIcon />} onClick={onClick} aria-label={`${member.name}さんを削除`}>
      削除
    </Button>
  )

/** デスクトップ：コレクション（テーブル）[H:page-layout][H:smarthr-table] */
const MemberTable = ({ members, onDelete }: { members: Member[]; onDelete: (m: Member) => void }) => {
  const { me } = useAppState()
  return (
    <Table>
      <thead>
        <tr>
          <Th>社員番号</Th>
          <Th>名前</Th>
          <Th>参加状況</Th>
          <Th>uチャンネル</Th>
          {me && <Th>操作</Th>}
        </tr>
      </thead>
      {members.length === 0 ? (
        <EmptyTableBody>
          <EmptyMessage />
        </EmptyTableBody>
      ) : (
        <tbody>
          {members.map((m) => (
            <tr key={m.id}>
              <Td>{empCode(m)}</Td>
              <Td>
                <Stack gap={0.25}>
                  <Person member={m} note={me?.id === m.id ? 'あなた' : undefined} />
                  <IncompleteNote member={m} />
                </Stack>
              </Td>
              <Td contentWidth="1px">
                <ActiveLabel member={m} />
              </Td>
              <Td>{m.channel ? `#${m.channel}` : ''}</Td>
              {me && (
                <Td contentWidth="1px">
                  {me.id === m.id ? (
                    <RouterTextLink href="/settings">設定を変更</RouterTextLink>
                  ) : (
                    <DeleteButton member={m} onClick={() => onDelete(m)} />
                  )}
                </Td>
              )}
            </tr>
          ))}
        </tbody>
      )}
    </Table>
  )
}

/** モバイル：コレクション（リスト）。詳細ビューを持たないので、操作はアイコンボタン 1 つ [H:smarthr-list] */
const MemberList = ({ members, onDelete }: { members: Member[]; onDelete: (m: Member) => void }) => {
  const { me } = useAppState()
  return (
    <Panel padding={members.length === 0 ? 1 : undefined}>
      {members.length === 0 ? (
        <EmptyMessage />
      ) : (
      <ul className="shr-m-0 shr-list-none shr-ps-0">
        {members.map((m, i) => (
          <li key={m.id} className={i > 0 ? 'shr-border-t-shorthand' : undefined}>
            <Cluster justify="space-between" align="center" className="shr-p-1">
              <Stack gap={0.25}>
                <Person member={m} note={me?.id === m.id ? 'あなた' : undefined} />
                <Cluster align="center">
                  <ActiveLabel member={m} />
                  <Text size="S" color="TEXT_GREY" leading="TIGHT">
                    社員番号：{empCode(m)}
                  </Text>
                </Cluster>
                <IncompleteNote member={m} />
              </Stack>
              {me &&
                (me.id === m.id ? (
                  <RouterTextLink href="/settings">設定を変更</RouterTextLink>
                ) : (
                  <DeleteButton member={m} onClick={() => onDelete(m)} iconOnly />
                ))}
            </Cluster>
          </li>
        ))}
      </ul>
      )}
    </Panel>
  )
}

const EmptyMessage = () => {
  const { me, login } = useAppState()
  return (
    <Center padding={1.5}>
      <Stack align="center">
        <p>表示するデータはありません。</p>
        <Text as="p" size="S" color="TEXT_GREY">
          メンバーは Slack でログインすると追加されます。
        </Text>
        {!me && (
          <Button size="S" prefix={<FaRightToBracketIcon />} onClick={login}>
            Slack でログイン
          </Button>
        )}
      </Stack>
    </Center>
  )
}

export const Members = () => {
  const { members, me, deleteTargetId, failDelete, deleteMember, setNotice } = useAppState()
  const { mobile } = useEnvironment()
  const [target, setTarget] = useState<Member | null>(
    () => (deleteTargetId && members.find((m) => m.id === deleteTargetId)) || null,
  )
  const [status, setStatus] = useState<
    { status: 'processing' } | { status: 'error'; text: string } | undefined
  >(() =>
    deleteTargetId && failDelete
      ? { status: 'error', text: '削除できませんでした。通信状況を確認して、もう一度「削除」を押してください。' }
      : undefined,
  )

  const sorted = [...members].sort((a, b) => a.id - b.id)
  const activeCount = members.filter((m) => m.active).length
  const inactiveCount = members.length - activeCount

  const open = (m: Member) => {
    setStatus(undefined)
    setTarget(m)
  }
  const close = () => {
    setTarget(null)
    setStatus(undefined)
  }

  return (
    <Layout title="メンバー">
      <Container>
        <Stack gap={2}>
          <Stack gap={0.5}>
            <PageHeading>メンバー</PageHeading>
            <p>
              一度でもログインしたことのある人を、社員番号順に表示しています。「参加」の人だけが組み合わせに入ります。
            </p>
          </Stack>
          <Section>
            <Stack>
              <Cluster justify="space-between" align="center" gap={1}>
                <Heading>参加状況</Heading>
                <span>
                  参加 {activeCount} 人・不参加 {inactiveCount} 人（全 {members.length} 人）
                </span>
              </Cluster>
              {mobile ? (
                <MemberList members={sorted} onDelete={open} />
              ) : (
                <Panel>
                  <MemberTable members={sorted} onDelete={open} />
                </Panel>
              )}
              {!me && members.length > 0 && (
                <Text as="p" size="S" color="TEXT_GREY">
                  ログインすると、退職した人などをメンバーから削除できます。
                </Text>
              )}
            </Stack>
          </Section>
        </Stack>
      </Container>

      {/* 削除ダイアログ [H:delete-dialog] */}
      <ControlledActionDialog
        isOpen={target !== null}
        heading="メンバーの削除"
        size="S"
        actionButton={{ text: '削除', theme: 'danger' }}
        responseStatus={status}
        onClickClose={close}
        onClickAction={async () => {
          if (!target) return
          setStatus({ status: 'processing' })
          try {
            await deleteMember(target.id)
            setNotice({ type: 'success', text: `${target.name}さんをメンバーから削除しました。` })
            close()
          } catch {
            setStatus({
              status: 'error',
              text: '削除できませんでした。通信状況を確認して、もう一度「削除」を押してください。',
            })
          }
        }}
      >
        {target && (
          <Stack gap={1.5}>
            <p>{'以下のメンバーを削除しますか？\u3000この操作は元に戻せません。'}</p>
            <DefinitionList>
              <DefinitionListItem term={{ text: '削除するメンバー', styleType: 'blockTitle' }}>
                {target.name}（社員番号 {empCode(target)}）
              </DefinitionListItem>
            </DefinitionList>
            {target.active && (
              <Text as="p" icon={<WarningIcon />}>
                このメンバーは CT に参加中です。削除すると、今週以降の全員の組み合わせが組み直されます。
              </Text>
            )}
          </Stack>
        )}
      </ControlledActionDialog>
    </Layout>
  )
}

